package com.agacostays.payroll.service.impl; import com.agacostays.payroll.dto.response.*;import com.agacostays.payroll.entity.*;import com.agacostays.payroll.enums.*;import com.agacostays.payroll.event.*;import com.agacostays.payroll.event.producer.*;import com.agacostays.payroll.exception.*;import com.agacostays.payroll.mapper.*;import com.agacostays.payroll.repository.*;import com.agacostays.payroll.service.*;import com.agacostays.payroll.storage.*;import org.springframework.stereotype.Service;import jakarta.transaction.Transactional;@Service public class SalarySlipServiceImpl implements SalarySlipService{final SalarySlipRepository repo;final PayrollRepository payrollRepo;final SalarySlipMapper mapper;final SalarySlipStorageService storage;final PayrollEventProducer prod;public SalarySlipServiceImpl(SalarySlipRepository r,PayrollRepository p,SalarySlipMapper m,SalarySlipStorageService s,PayrollEventProducer pr){repo=r;payrollRepo=p;mapper=m;storage=s;prod=pr;}@Transactional public SalarySlipResponse generate(Long id){Payroll p=payrollRepo.findById(id).orElseThrow(()->new ResourceNotFoundException("Payroll not found: "+id));var old=repo.findByPayrollId(id);if(old.isPresent())return mapper.toResponse(old.get());String key="payroll-"+id;String url=storage.store(p,key);SalarySlip s=repo.save(SalarySlip.builder().payrollId(id).staffId(p.getStaffId()).month(p.getMonth()).year(p.getYear()).salarySlipUrl(url).sentEmailStatus(SalarySlipStatus.GENERATED).build());prod.slipGenerated(new SalarySlipGeneratedEvent(s.getSalarySlipId(),s.getPayrollId(),s.getStaffId(),s.getSalarySlipUrl()));return mapper.toResponse(s);}public SalarySlipResponse getByPayroll(Long id){return repo.findByPayrollId(id).map(mapper::toResponse).orElseThrow(()->new ResourceNotFoundException("Salary slip not found"));}public byte[] download(Long id){repo.findByPayrollId(id).orElseThrow(()->new ResourceNotFoundException("Salary slip not found"));return storage.read("payroll-"+id);}@Transactional public void sendEmail(Long id,String email){SalarySlip s=repo.findByPayrollId(id).orElseThrow(()->new ResourceNotFoundException("Salary slip not found"));s.setSentEmailStatus(SalarySlipStatus.SENT);repo.save(s);}}
